def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(token):
        if not token.isascii() or not token.isdigit():
            return None

        # Bounded chunks avoid Python's limit on long decimal conversions.
        value = 0
        for start in range(0, len(token), 9):
            chunk = token[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    def apply(tokens):
        verb = tokens[0]

        if verb == "undo":
            if not history:
                return False
            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            return True

        amount = None
        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(tokens[-1])
            if amount is None or (verb != "open" and amount == 0):
                return False

        name = tokens[1]
        previous = accounts.get(name)
        changes = ((name, previous),)

        if verb == "open":
            if previous is not None:
                return False
            accounts[name] = (amount, False)
        else:
            if previous is None:
                return False

            balance, frozen = previous

            if verb == "deposit":
                accounts[name] = (balance + amount, frozen)

            elif verb == "withdraw":
                if frozen or balance < amount:
                    return False
                accounts[name] = (balance - amount, frozen)

            elif verb == "transfer":
                destination = tokens[2]
                destination_state = accounts.get(destination)

                if (
                    name == destination
                    or destination_state is None
                    or frozen
                    or balance < amount
                ):
                    return False

                changes = (
                    (name, previous),
                    (destination, destination_state),
                )
                accounts[name] = (balance - amount, frozen)
                accounts[destination] = (
                    destination_state[0] + amount,
                    destination_state[1],
                )

            elif verb == "freeze":
                if frozen:
                    return False
                accounts[name] = (balance, True)

            elif verb == "unfreeze":
                if not frozen:
                    return False
                accounts[name] = (balance, False)

        history.append(changes)
        return True

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        if (
            arities.get(tokens[0]) != len(tokens)
            or any(not token for token in tokens)
            or not apply(tokens)
        ):
            rejected.append(index)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
